def reviewed_grade(tweak_id: object) -> str | None:
    """Reviewed grade for ``tweak_id``, or None when unreviewed.

    Fails closed by returning None rather than guessing: the caller
    decides what an unreviewed tweak should fall back to.
    """
    if not isinstance(tweak_id, str):
        return None
    return REVIEWED_GRADES.get(tweak_id.strip())
